// Check if boxes are separated
if (box1.max.x < box2.min.x || box1.min.x > box2.max.x ||
    box1.max.y < box2.min.y || box1.min.y > box2.max.y ||
    box1.max.z < box2.min.z || box1.min.z > box2.max.z)
{
    return BoxRelation::Separated;
}

// Check if boxes are adjacent (touching but not overlapping)
bool adjacentX = (std::abs(box1.max.x - box2.min.x) < std::numeric_limits<double>::epsilon()) ||
                 (std::abs(box1.min.x - box2.max.x) < std::numeric_limits<double>::epsilon());
bool adjacentY = (std::abs(box1.max.y - box2.min.y) < std::numeric_limits<double>::epsilon()) ||
                 (std::abs(box1.min.y - box2.max.y) < std::numeric_limits<double>::epsilon());
bool adjacentZ = (std::abs(box1.max.z - box2.min.z) < std::numeric_limits<double>::epsilon()) ||
                 (std::abs(box1.min.z - box2.max.z) < std::numeric_limits<double>::epsilon());

if ((adjacentX && ((box1.min.y <= box2.max.y && box1.max.y >= box2.min.y) ||
                   (box2.min.y <= box1.max.y && box2.max.y >= box1.min.y))) ||
    (adjacentY && ((box1.min.x <= box2.max.x && box1.max.x >= box2.min.x) ||
                   (box2.min.x <= box1.max.x && box2.max.x >= box1.min.x))) ||
    (adjacentZ && ((box1.min.x <= box2.max.x && box1.max.x >= box2.min.x) &&
                   (box1.min.y <= box2.max.y && box1.max.y >= box2.min.y))))
{
    return BoxRelation::Adjacent;
}

// Otherwise, they must be overlapping
return BoxRelation::Overlapped;
